import { Readable } from 'node:stream';

/**
 * An in-memory file, used to store a file that was not received as a multipart upload, such as an avatar downloaded
 * from an OAuth2 provider or an image generated by the application itself.
 */
export type FileBuffer = {
  /** The original file name, used to derive the stored name and its extension. */
  name: string;
  /** The media type of the content, checked against the `mimeType` of the file field. */
  mimeType: string;
  /** The file content. */
  data: Buffer;
  /** The content size in bytes checked against the size limit of the file field, defaults to the data buffer length. */
  size?: number;
  /** The content encoding, defaults to `7bit`. */
  encoding?: string;
};

/** A file part of a multipart upload, the shape of the files of `@fastify/multipart`. */
export type UploadedFile = {
  type: 'file';
  fieldname: string;
  filename: string;
  encoding: string;
  mimetype: string;
  /** The content, with the bytes read so far and whether the size limit truncated it. */
  file: Readable & { bytesRead: number; truncated: boolean };
};

/** A part of a multipart upload: a file, or a field the file services skip. */
export type UploadPart = UploadedFile | { type: 'field'; fieldname: string };
